@Override
public void afterCheckProject(@NonNull Context context) {
    Project project = context.getProject();
    List<JobServiceInfo> jobServices = sJobServices.get(project);
    List<ManifestServiceInfo> manifestServices = sManifestServices.get(project);
    if (jobServices == null || manifestServices == null) { ... }
    // For each job service, find matching manifest service
    for (JobServiceInfo job : jobServices) {
        ManifestServiceInfo match = null;
        for (ManifestServiceInfo service : manifestServices) {
            if (sameClassName(job.name, service.name)) { match = service; break; }
        }
        if (match == null) {
            context.report(ISSUE, job.location, "JobService " + job.name + " must be registered in the manifest");
        } else if (!match.hasPermission) {
            context.report(ISSUE, match.location, "JobService " + job.name + " must require the permission " + BIND_JOB_SERVICE);
        }
    }
    // Optionally check reverse: manifest service with permission but no JobService class
    for (ManifestServiceInfo service : manifestServices) {
        if (service.hasPermission) {
            boolean found = false;
            for (JobServiceInfo job : jobServices) {
                if (sameClassName(job.name, service.name)) { found = true; break; }
            }
            if (!found) {
                context.report(ISSUE, service.location, "Service " + service.name + " does not extend JobService");
            }
        }
    }
    sJobServices.remove(project);
    sManifestServices.remove(project);
}
```

